entity system_preprocess_v_0_0_UART_top is
  port (
    tx : out STD_LOGIC;
    debug_uart_byte_valid : out STD_LOGIC;
    debug_uart_busy : out STD_LOGIC;
    debug_uart_byte : out STD_LOGIC_VECTOR ( 7 downto 0 );
    clk : in STD_LOGIC;
    reset : in STD_LOGIC;
    inf_done : in STD_LOGIC;
    inf_data : in STD_LOGIC_VECTOR ( 15 downto 0 )
  );
  attribute ORIG_REF_NAME : string;
  attribute ORIG_REF_NAME of system_preprocess_v_0_0_UART_top : entity is "UART_top";
end system_preprocess_v_0_0_UART_top;

architecture STRUCTURE of system_preprocess_v_0_0_UART_top is
  signal U_InfDataCtrl_n_1 : STD_LOGIC;
  signal U_InfDataCtrl_n_2 : STD_LOGIC;
  signal U_SYNC_UART_n_1 : STD_LOGIC;
  signal \^debug_uart_byte\ : STD_LOGIC_VECTOR ( 7 downto 0 );
  signal o_data : STD_LOGIC_VECTOR ( 7 downto 0 );
  signal w_fifo_empty : STD_LOGIC;
  signal w_fifo_full : STD_LOGIC;
  signal w_fifo_push : STD_LOGIC;
  signal w_inf_done : STD_LOGIC;
  signal w_uart_ready : STD_LOGIC;
begin
  debug_uart_byte(7 downto 0) <= \^debug_uart_byte\(7 downto 0);
U_InfDataCtrl: entity work.system_preprocess_v_0_0_InfDataController
     port map (
      E(0) => U_SYNC_UART_n_1,
      I227 => U_InfDataCtrl_n_1,
      Q(0) => U_InfDataCtrl_n_2,
      clk => clk,
      inf_data(15 downto 0) => inf_data(15 downto 0),
      \o_data_reg[7]_0\(7 downto 0) => o_data(7 downto 0),
      reset => reset,
      w_fifo_full => w_fifo_full,
      w_fifo_push => w_fifo_push,
      w_inf_done => w_inf_done
    );
U_SYNC_UART: entity work.system_preprocess_v_0_0_SYNC_2FF
     port map (
      E(0) => U_SYNC_UART_n_1,
      Q(0) => U_InfDataCtrl_n_2,
      clk => clk,
      inf_done => inf_done,
      reset => reset,
      w_inf_done => w_inf_done
    );
U_UART_FIFO: entity work.system_preprocess_v_0_0_fifo
     port map (
      I227 => U_InfDataCtrl_n_1,
      clk => clk,
      debug_uart_byte(7 downto 0) => \^debug_uart_byte\(7 downto 0),
      reset => reset,
      \shift_reg_reg[7]\(7 downto 0) => o_data(7 downto 0),
      w_fifo_empty => w_fifo_empty,
      w_fifo_full => w_fifo_full,
      w_fifo_push => w_fifo_push,
      w_uart_ready => w_uart_ready
    );
U_UART_TX: entity work.system_preprocess_v_0_0_uart_tx
     port map (
      clk => clk,
      debug_uart_busy => debug_uart_busy,
      debug_uart_byte(7 downto 0) => \^debug_uart_byte\(7 downto 0),
      debug_uart_byte_valid => debug_uart_byte_valid,
      reset => reset,
      tx => tx,
      w_fifo_empty => w_fifo_empty,
      w_uart_ready => w_uart_ready
    );
end STRUCTURE;
